SELECT
    dp1.Object.qserv_trans_id AS qserv_trans_id_raw,
    dp1.Object.objectId AS objectId_raw,
    dp1.Object.iauId AS iauId_raw,
    dp1.Object.ra_PS AS ra_PS_raw,
    dp1.Object.ra_PS_Sigma AS ra_PS_Sigma_raw,
    dp1.Object.decl_PS AS decl_PS_raw,
    dp1.Object.decl_PS_Sigma AS decl_PS_Sigma_raw,
    dp1.Object.radecl_PS_Cov AS radecl_PS_Cov_raw,
    dp1.Object.htmId20 AS htmId20_raw,
    dp1.Object.ra_SG AS ra_SG_raw,
    dp1.Object.ra_SG_Sigma AS ra_SG_Sigma_raw,
    dp1.Object.decl_SG AS decl_SG_raw,
    dp1.Object.decl_SG_Sigma AS decl_SG_Sigma_raw,
    dp1.Object.radecl_SG_Cov AS radecl_SG_Cov_raw,
    dp1.Object.raRange AS raRange_raw,
    dp1.Object.declRange AS declRange_raw,
    dp1.Object.muRa_PS AS muRa_PS_raw,
    dp1.Object.muRa_PS_Sigma AS muRa_PS_Sigma_raw,
    dp1.Object.muDecl_PS AS muDecl_PS_raw,
    dp1.Object.muDecl_PS_Sigma AS muDecl_PS_Sigma_raw,
    dp1.Object.muRaDecl_PS_Cov AS muRaDecl_PS_Cov_raw,
    dp1.Object.parallax_PS AS parallax_PS_raw,
    dp1.Object.parallax_PS_Sigma AS parallax_PS_Sigma_raw,
    dp1.Object.canonicalFilterId AS canonicalFilterId_raw,
    dp1.Object.extendedness AS extendedness_raw,
    dp1.Object.varProb AS varProb_raw,
    dp1.Object.earliestObsTime AS earliestObsTime_raw,
    dp1.Object.latestObsTime AS latestObsTime_raw,
    dp1.Object.meanObsTime AS meanObsTime_raw,
    dp1.Object.flags AS flags_raw,
    dp1.Object.uNumObs AS uNumObs_raw,
    dp1.Object.uExtendedness AS uExtendedness_raw,
    dp1.Object.uVarProb AS uVarProb_raw,
    dp1.Object.uRaOffset_PS AS uRaOffset_PS_raw,
    dp1.Object.uRaOffset_PS_Sigma AS uRaOffset_PS_Sigma_raw,
    dp1.Object.uDeclOffset_PS AS uDeclOffset_PS_raw,
    dp1.Object.uDeclOffset_PS_Sigma AS uDeclOffset_PS_Sigma_raw,
    dp1.Object.uRaDeclOffset_PS_Cov AS uRaDeclOffset_PS_Cov_raw,
    dp1.Object.uRaOffset_SG AS uRaOffset_SG_raw,
    dp1.Object.uRaOffset_SG_Sigma AS uRaOffset_SG_Sigma_raw,
    dp1.Object.uDeclOffset_SG AS uDeclOffset_SG_raw,
    dp1.Object.uDeclOffset_SG_Sigma AS uDeclOffset_SG_Sigma_raw,
    dp1.Object.uRaDeclOffset_SG_Cov AS uRaDeclOffset_SG_Cov_raw,
    dp1.Object.uLnL_PS AS uLnL_PS_raw,
    dp1.Object.uLnL_SG AS uLnL_SG_raw,
    dp1.Object.coord_dec AS coord_dec_raw,
    dp1.Object.coord_decErr AS coord_decErr_raw,
    dp1.Object.coord_ra AS coord_ra_raw,
    dp1.Object.coord_ra_dec_Cov AS coord_ra_dec_Cov_raw,
    dp1.Object.coord_raErr AS coord_raErr_raw,
    dp1.Object.deblend_failed AS deblend_failed_raw,
    dp1.Object.deblend_incompleteData AS deblend_incompleteData_raw,
    dp1.Object.deblend_isolatedParent AS deblend_isolatedParent_raw,
    dp1.Object.deblend_iterations AS deblend_iterations_raw,
    dp1.Object.deblend_logL AS deblend_logL_raw,
    dp1.Object.deblend_masked AS deblend_masked_raw,
    dp1.Object.deblend_nChild AS deblend_nChild_raw,
    dp1.Object.deblend_nPeaks AS deblend_nPeaks_raw,
    dp1.Object.deblend_parentTooBig AS deblend_parentTooBig_raw,
    dp1.Object.deblend_peak_center_x AS deblend_peak_center_x_raw,
    ((dp1.Object.qserv_trans_id + dp1.Object.decl_SG) * 1) AS expr_0_qserv_trans_id,
    ((dp1.Object.objectId + dp1.Object.decl_SG_Sigma) * 2) AS expr_1_objectId,
    ((dp1.Object.iauId + dp1.Object.radecl_SG_Cov) * 3) AS expr_2_iauId,
    ((dp1.Object.ra_PS + dp1.Object.raRange) * 4) AS expr_3_ra_PS,
    ((dp1.Object.ra_PS_Sigma + dp1.Object.declRange) * 5) AS expr_4_ra_PS_Sigma,
    ((dp1.Object.decl_PS + dp1.Object.muRa_PS) * 1) AS expr_5_decl_PS,
    ((dp1.Object.decl_PS_Sigma + dp1.Object.muRa_PS_Sigma) * 2) AS expr_6_decl_PS_Sigma,
    ((dp1.Object.radecl_PS_Cov + dp1.Object.muDecl_PS) * 3) AS expr_7_radecl_PS_Cov,
    ((dp1.Object.htmId20 + dp1.Object.muDecl_PS_Sigma) * 4) AS expr_8_htmId20,
    ((dp1.Object.ra_SG + dp1.Object.muRaDecl_PS_Cov) * 5) AS expr_9_ra_SG,
    ((dp1.Object.ra_SG_Sigma + dp1.Object.parallax_PS) * 1) AS expr_10_ra_SG_Sigma,
    ((dp1.Object.decl_SG + dp1.Object.parallax_PS_Sigma) * 2) AS expr_11_decl_SG,
    ((dp1.Object.decl_SG_Sigma + dp1.Object.canonicalFilterId) * 3) AS expr_12_decl_SG_Sigma,
    ((dp1.Object.radecl_SG_Cov + dp1.Object.extendedness) * 4) AS expr_13_radecl_SG_Cov,
    ((dp1.Object.raRange + dp1.Object.varProb) * 5) AS expr_14_raRange,
    ((dp1.Object.declRange + dp1.Object.earliestObsTime) * 1) AS expr_15_declRange,
    ((dp1.Object.muRa_PS + dp1.Object.latestObsTime) * 2) AS expr_16_muRa_PS,
    ((dp1.Object.muRa_PS_Sigma + dp1.Object.meanObsTime) * 3) AS expr_17_muRa_PS_Sigma,
    ((dp1.Object.muDecl_PS + dp1.Object.flags) * 4) AS expr_18_muDecl_PS,
    ((dp1.Object.muDecl_PS_Sigma + dp1.Object.uNumObs) * 5) AS expr_19_muDecl_PS_Sigma,
    ((dp1.Object.muRaDecl_PS_Cov + dp1.Object.uExtendedness) * 1) AS expr_20_muRaDecl_PS_Cov,
    ((dp1.Object.parallax_PS + dp1.Object.uVarProb) * 2) AS expr_21_parallax_PS,
    ((dp1.Object.parallax_PS_Sigma + dp1.Object.uRaOffset_PS) * 3) AS expr_22_parallax_PS_Sigma,
    ((dp1.Object.canonicalFilterId + dp1.Object.uRaOffset_PS_Sigma) * 4) AS expr_23_canonicalFilterId,
    ((dp1.Object.extendedness + dp1.Object.uDeclOffset_PS) * 5) AS expr_24_extendedness,
    ((dp1.Object.varProb + dp1.Object.uDeclOffset_PS_Sigma) * 1) AS expr_25_varProb,
    ((dp1.Object.earliestObsTime + dp1.Object.uRaDeclOffset_PS_Cov) * 2) AS expr_26_earliestObsTime,
    ((dp1.Object.latestObsTime + dp1.Object.uRaOffset_SG) * 3) AS expr_27_latestObsTime,
    ((dp1.Object.meanObsTime + dp1.Object.uRaOffset_SG_Sigma) * 4) AS expr_28_meanObsTime,
    ((dp1.Object.flags + dp1.Object.uDeclOffset_SG) * 5) AS expr_29_flags,
    ((dp1.Object.uNumObs + dp1.Object.uDeclOffset_SG_Sigma) * 1) AS expr_30_uNumObs,
    ((dp1.Object.uExtendedness + dp1.Object.uRaDeclOffset_SG_Cov) * 2) AS expr_31_uExtendedness,
    ((dp1.Object.uVarProb + dp1.Object.uLnL_PS) * 3) AS expr_32_uVarProb,
    ((dp1.Object.uRaOffset_PS + dp1.Object.uLnL_SG) * 4) AS expr_33_uRaOffset_PS,
    ((dp1.Object.uRaOffset_PS_Sigma + dp1.Object.coord_dec) * 5) AS expr_34_uRaOffset_PS_Sigma
FROM dp1.Object
WHERE
    (dp1.Object.qserv_trans_id > 0 AND dp1.Object.objectId < 1 AND dp1.Object.iauId >= 2)
    OR (dp1.Object.ra_PS > 3 AND dp1.Object.ra_PS_Sigma < 4 AND dp1.Object.decl_PS >= 5)
    OR (dp1.Object.decl_PS_Sigma > 6 AND dp1.Object.radecl_PS_Cov < 7 AND dp1.Object.htmId20 >= 8)
    OR (dp1.Object.ra_SG > 9 AND dp1.Object.ra_SG_Sigma < 10 AND dp1.Object.decl_SG >= 11)
    OR (dp1.Object.decl_SG_Sigma > 12 AND dp1.Object.radecl_SG_Cov < 13 AND dp1.Object.raRange >= 14)
    OR (dp1.Object.declRange > 15 AND dp1.Object.muRa_PS < 16 AND dp1.Object.muRa_PS_Sigma >= 17)
    OR (dp1.Object.muDecl_PS > 18 AND dp1.Object.muDecl_PS_Sigma < 19 AND dp1.Object.muRaDecl_PS_Cov >= 0)
    OR (dp1.Object.parallax_PS > 1 AND dp1.Object.parallax_PS_Sigma < 2 AND dp1.Object.canonicalFilterId >= 3)
    OR (dp1.Object.extendedness > 4 AND dp1.Object.varProb < 5 AND dp1.Object.earliestObsTime >= 6)
    OR (dp1.Object.latestObsTime > 7 AND dp1.Object.meanObsTime < 8 AND dp1.Object.flags >= 9)
    OR (dp1.Object.uNumObs > 10 AND dp1.Object.uExtendedness < 11 AND dp1.Object.uVarProb >= 12)
    OR (dp1.Object.uRaOffset_PS > 13 AND dp1.Object.uRaOffset_PS_Sigma < 14 AND dp1.Object.uDeclOffset_PS >= 15)
ORDER BY dp1.Object.objectId
